from fastapi.testclient import TestClient
from app.main import app

client = TestClient(app)

try:
    for _ in range(60):
        response = client.get("/tasks/")
        assert response.status_code == 200
except AssertionError:
    print("Test failed: Not all requests received a 2xx response.")

from fastapi.testclient import TestClient
from app.main import app

client = TestClient(app)

throttled = False
try:
    for _ in range(61):
        response = client.get("/tasks/")
        if response.status_code >= 400:
            throttled = True
            break
    assert throttled, "Test failed: No request was throttled."
except AssertionError:
    print("Test failed: No request was throttled.")

from fastapi.testclient import TestClient
from app.main import app

client = TestClient(app)

try:
    for i in range(61):
        response = client.get("/tasks/")
        if i < 60:
            assert response.status_code == 200, f"Request {i+1} failed"
        else:
            assert response.status_code >= 400, "61st request was not throttled"
except AssertionError as e:
    print(f"Test failed: {e}")

